import { Canvas, useFrame } from '@react-three/fiber'
import { Line, OrbitControls } from '@react-three/drei'
import { useEffect, useLayoutEffect, useMemo, useRef, useState, type ComponentRef } from 'react'
import * as THREE from 'three'
import type { AirCityRecord, AirMetric, CityKey } from '../data/ecology'
import { useMotionProfile, type MotionProfile } from '../hooks/useMotionProfile'
import { mapRecordToTerrain, particleCountForProfile, sampleTerrainHeight } from './particleTerrainMath'

export interface ParticleTerrainSceneProps {
  average: number | null
  metric: AirMetric
  periodLabel: string
  records: AirCityRecord[]
  selectedCity: CityKey
  scanning: boolean
  pulseKey: string
  resetViewSignal: number
  onSelectCity: (city: CityKey) => void
}

const palette = ['#00B8CC', '#45FF78', '#CBFF38', '#FFD84D', '#FF8C3A', '#FF453A']

const hash = (x: number, y: number) => {
  const value = Math.sin(x * 12.9898 + y * 78.233) * 43758.5453
  return value - Math.floor(value)
}

function createSurfaceGeometry(profile: MotionProfile) {
  const [columns, rows] = profile === 'full' ? [240, 200] : profile === 'lite' ? [170, 120] : [120, 90]
  const positions = new Float32Array(columns * rows * 3)
  const elevations = new Float32Array(columns * rows)
  const randoms = new Float32Array(columns * rows)
  let offset = 0
  for (let row = 0; row < rows; row += 1) {
    for (let column = 0; column < columns; column += 1) {
      const jitterX = (hash(column, row) - .5) * .027
      const jitterZ = (hash(row + 81, column + 37) - .5) * .027
      const x = column / (columns - 1) * 11.7 - 5.85 + jitterX
      const z = row / (rows - 1) * 8.25 - 4.125 + jitterZ
      const y = sampleTerrainHeight(x, z)
      positions[offset * 3] = x
      positions[offset * 3 + 1] = y
      positions[offset * 3 + 2] = z
      elevations[offset] = THREE.MathUtils.clamp((y + 1.18) / 3.9, 0, 1)
      randoms[offset] = hash(column + 13, row + 97)
      offset += 1
    }
  }
  const geometry = new THREE.BufferGeometry()
  geometry.setAttribute('position', new THREE.BufferAttribute(positions, 3))
  geometry.setAttribute('aElevation', new THREE.BufferAttribute(elevations, 1))
  geometry.setAttribute('aRandom', new THREE.BufferAttribute(randoms, 1))
  geometry.computeBoundingSphere()
  return geometry
}

function createSkirtGeometry(profile: MotionProfile) {
  const edgeSamples = profile === 'full' ? 150 : profile === 'lite' ? 90 : 58
  const depthSamples = profile === 'full' ? 14 : 9
  const points: number[] = []
  const elevations: number[] = []
  const randoms: number[] = []
  const addEdge = (x: number, z: number, seed: number) => {
    const top = sampleTerrainHeight(x, z)
    for (let level = 0; level < depthSamples; level += 1) {
      const t = level / Math.max(1, depthSamples - 1)
      points.push(x, THREE.MathUtils.lerp(top, -1.78, t), z)
      elevations.push(Math.max(0, (top + 1.18) / 3.9) * (1 - t * .72))
      randoms.push(hash(seed, level))
    }
  }
  for (let index = 0; index < edgeSamples; index += 1) {
    const t = index / (edgeSamples - 1)
    const x = THREE.MathUtils.lerp(-5.85, 5.85, t)
    const z = THREE.MathUtils.lerp(-4.125, 4.125, t)
    addEdge(x, -4.125, index)
    addEdge(x, 4.125, index + 200)
    addEdge(-5.85, z, index + 400)
    addEdge(5.85, z, index + 600)
  }
  const geometry = new THREE.BufferGeometry()
  geometry.setAttribute('position', new THREE.Float32BufferAttribute(points, 3))
  geometry.setAttribute('aElevation', new THREE.Float32BufferAttribute(elevations, 1))
  geometry.setAttribute('aRandom', new THREE.Float32BufferAttribute(randoms, 1))
  return geometry
}

const vertexShader = `
  attribute float aElevation;
  attribute float aRandom;
  uniform float uTime;
  uniform float uPointScale;
  uniform float uEnergy;
  varying float vElevation;
  varying float vRandom;
  void main() {
    vElevation = aElevation;
    vRandom = aRandom;
    vec3 displaced = position;
    displaced.y += sin(uTime * 0.8 + aRandom * 18.0) * 0.008 * uEnergy;
    vec4 mvPosition = modelViewMatrix * vec4(displaced, 1.0);
    gl_Position = projectionMatrix * mvPosition;
    gl_PointSize = clamp(uPointScale * (0.75 + aElevation * 0.85 + aRandom * 0.15) / max(1.0, -mvPosition.z), 1.15, 4.8);
  }
`

const fragmentShader = `
  uniform float uEnergy;
  uniform float uOpacity;
  varying float vElevation;
  varying float vRandom;
  void main() {
    vec2 p = gl_PointCoord - vec2(0.5);
    float distanceToCenter = length(p);
    if (distanceToCenter > 0.5) discard;
    float core = smoothstep(0.5, 0.08, distanceToCenter);
    vec3 cyan = vec3(0.0, 0.72, 0.80);
    vec3 green = vec3(0.27, 1.0, 0.47);
    vec3 lime = vec3(0.80, 1.0, 0.22);
    vec3 gold = vec3(1.0, 0.85, 0.30);
    vec3 orange = vec3(1.0, 0.55, 0.23);
    vec3 red = vec3(1.0, 0.27, 0.23);
    vec3 color = mix(cyan, green, smoothstep(0.02, 0.30, vElevation));
    color = mix(color, lime, smoothstep(0.25, 0.50, vElevation));
    color = mix(color, gold, smoothstep(0.42, 0.60, vElevation));
    color = mix(color, orange, smoothstep(0.46, 0.64, vElevation));
    color = mix(color, red, smoothstep(0.60, 0.78, vElevation));
    float shimmer = 0.82 + vRandom * 0.25 + uEnergy * 0.08;
    gl_FragColor = vec4(color * shimmer, core * uOpacity);
  }
`

function ParticleLayer({ profile, energy, skirt = false }: { profile: MotionProfile; energy: number; skirt?: boolean }) {
  const geometry = useMemo(() => skirt ? createSkirtGeometry(profile) : createSurfaceGeometry(profile), [profile, skirt])
  const material = useMemo(() => new THREE.ShaderMaterial({
    uniforms: {
      uTime: { value: 0 },
      uPointScale: { value: profile === 'full' ? 31 : profile === 'lite' ? 27 : 23 },
      uEnergy: { value: energy },
      uOpacity: { value: skirt ? .52 : .95 },
    },
    vertexShader,
    fragmentShader,
    transparent: true,
    depthWrite: false,
    blending: THREE.AdditiveBlending,
  }), [energy, profile, skirt])

  useEffect(() => { material.uniforms.uEnergy.value = energy }, [energy, material])
  useEffect(() => () => { geometry.dispose(); material.dispose() }, [geometry, material])
  useFrame((state) => { if (profile !== 'reduced') material.uniforms.uTime.value = state.clock.elapsedTime })
  return <points geometry={geometry} material={material} frustumCulled={false} />
}

function DataBeacon({ record, metric, min, max, selected, scanning, onSelect }: {
  record: AirCityRecord
  metric: AirMetric
  min: number
  max: number
  selected: boolean
  scanning: boolean
  onSelect: () => void
}) {
  const group = useRef<THREE.Group>(null)
  const position = useMemo(() => mapRecordToTerrain(record), [record])
  const normalized = (record[metric] - min) / Math.max(1, max - min)
  const color = useMemo(() => new THREE.Color('#45FF78').lerp(new THREE.Color('#FFD84D'), Math.min(1, normalized * 1.35)).lerp(new THREE.Color('#FF8C3A'), Math.max(0, normalized - .58)), [normalized])
  useFrame((state) => {
    if (!group.current) return
    const pulse = 1 + Math.sin(state.clock.elapsedTime * (scanning ? 7 : 2.8) + record.x) * (selected ? .12 : .05)
    group.current.scale.setScalar(pulse)
  })
  return (
    <group ref={group} position={[position.x, position.y, position.z]}>
      <mesh
        onClick={(event) => { event.stopPropagation(); onSelect() }}
        onPointerOver={(event) => { event.stopPropagation(); document.body.style.cursor = 'pointer' }}
        onPointerOut={() => { document.body.style.cursor = '' }}
      >
        <sphereGeometry args={[selected ? .105 : .065 + normalized * .025, 14, 14]} />
        <meshBasicMaterial color={selected ? '#FAF7EF' : color} transparent opacity={.98} />
      </mesh>
      <mesh position={[0, .38, 0]}>
        <cylinderGeometry args={[.008, .014, .76, 8]} />
        <meshBasicMaterial color={color} transparent opacity={scanning || selected ? .9 : .48} blending={THREE.AdditiveBlending} />
      </mesh>
      <mesh rotation={[-Math.PI / 2, 0, 0]}>
        <ringGeometry args={[.13, .17, 28]} />
        <meshBasicMaterial color={color} transparent opacity={selected ? .95 : .42} side={THREE.DoubleSide} blending={THREE.AdditiveBlending} />
      </mesh>
    </group>
  )
}

function Scanner({ scanning, pulseKey, accent, profile }: { scanning: boolean; pulseKey: string; accent: string; profile: MotionProfile }) {
  const ringGroup = useRef<THREE.Group>(null)
  const beam = useRef<THREE.Mesh>(null)
  const dot = useRef<THREE.Mesh>(null)
  const ticks = useRef<THREE.InstancedMesh>(null)
  const boost = useRef(0)
  const ringPoints = useMemo(() => Array.from({ length: 129 }, (_, index) => {
    const angle = index / 128 * Math.PI * 2
    return [Math.cos(angle) * 6.22, -.77, Math.sin(angle) * 6.22] as [number, number, number]
  }), [])

  useLayoutEffect(() => {
    if (!ticks.current) return
    const object = new THREE.Object3D()
    for (let index = 0; index < 96; index += 1) {
      const angle = index / 96 * Math.PI * 2
      object.position.set(Math.cos(angle) * 6.26, -.77, Math.sin(angle) * 6.26)
      object.rotation.set(0, -angle, 0)
      object.scale.set(index % 8 === 0 ? 1.8 : .7, 1, 1)
      object.updateMatrix()
      ticks.current.setMatrixAt(index, object.matrix)
    }
    ticks.current.instanceMatrix.needsUpdate = true
  }, [])

  useEffect(() => { boost.current = 1 }, [pulseKey])
  useFrame((state, delta) => {
    boost.current = Math.max(0, boost.current - delta * .55)
    const speed = profile === 'reduced' ? 0 : scanning ? .62 : .055 + boost.current * .34
    if (ringGroup.current) ringGroup.current.rotation.y += delta * speed
    if (beam.current) {
      beam.current.rotation.y += delta * (profile === 'reduced' ? 0 : scanning ? 1.25 : .11)
      const material = beam.current.material as THREE.MeshBasicMaterial
      material.opacity = scanning ? .11 : .025 + boost.current * .045
    }
    if (dot.current) {
      const angle = state.clock.elapsedTime * (scanning ? 1.9 : .36)
      dot.current.position.set(Math.cos(angle) * 6.22, -.72, Math.sin(angle) * 6.22)
    }
  })

  return (
    <group>
      <group ref={ringGroup}>
        <mesh rotation={[Math.PI / 2, 0, 0]} position={[0, -.77, 0]}>
          <torusGeometry args={[6.22, .022, 6, 180]} />
          <meshBasicMaterial color="#FFD84D" transparent opacity={.72} blending={THREE.AdditiveBlending} />
        </mesh>
        <mesh rotation={[Math.PI / 2, 0, 0]} position={[0, -.52, 0]}>
          <torusGeometry args={[5.54, .012, 5, 150]} />
          <meshBasicMaterial color={accent} transparent opacity={.4} blending={THREE.AdditiveBlending} />
        </mesh>
        <instancedMesh ref={ticks} args={[undefined, undefined, 96]}>
          <boxGeometry args={[.12, .018, .012]} />
          <meshBasicMaterial color="#FFD84D" transparent opacity={.74} />
        </instancedMesh>
        <Line points={ringPoints} color="#FAF7EF" transparent opacity={.16} lineWidth={.55} dashed dashSize={.11} gapSize={.08} />
      </group>
      <mesh ref={beam} position={[0, .48, 0]}>
        <planeGeometry args={[12.4, 4.6]} />
        <meshBasicMaterial color={accent} transparent opacity={.035} depthWrite={false} side={THREE.DoubleSide} blending={THREE.AdditiveBlending} />
      </mesh>
      <mesh ref={dot}>
        <sphereGeometry args={[.065, 12, 12]} />
        <meshBasicMaterial color="#FAF7EF" blending={THREE.AdditiveBlending} />
      </mesh>
    </group>
  )
}

function Scene({ props, profile }: { props: ParticleTerrainSceneProps; profile: MotionProfile }) {
  const controls = useRef<ComponentRef<typeof OrbitControls>>(null)
  const terrainGroup = useRef<THREE.Group>(null)
  const values = props.records.map((record) => record[props.metric])
  const min = Math.min(...values)
  const max = Math.max(...values)
  const energy = THREE.MathUtils.clamp(((props.average ?? 12) - 8) / 28, .08, 1)
  const accent = props.metric === 'pm25' ? '#CBFF38' : '#00B8CC'

  useEffect(() => { controls.current?.reset() }, [props.resetViewSignal])
  useEffect(() => () => { document.body.style.cursor = '' }, [])
  useFrame((state, delta) => {
    if (!terrainGroup.current || profile !== 'full') return
    terrainGroup.current.position.y = Math.sin(state.clock.elapsedTime * .32) * .035
    if (!props.scanning) terrainGroup.current.rotation.y += delta * .009
  })

  return (
    <>
      <color attach="background" args={['#030705']} />
      <fog attach="fog" args={['#030705', 10, 23]} />
      <ambientLight intensity={.25} />
      <pointLight position={[0, 7, 2]} intensity={3.2} color="#CBFF38" distance={16} />
      <group ref={terrainGroup}>
        <ParticleLayer profile={profile} energy={energy} />
        <ParticleLayer profile={profile} energy={energy} skirt />
        {props.records.map((record) => (
          <DataBeacon
            key={record.city}
            record={record}
            metric={props.metric}
            min={min}
            max={max}
            selected={record.city === props.selectedCity}
            scanning={props.scanning}
            onSelect={() => props.onSelectCity(record.city)}
          />
        ))}
      </group>
      <Scanner scanning={props.scanning} pulseKey={props.pulseKey} accent={accent} profile={profile} />
      <gridHelper args={[19, 38, '#193d2f', '#0b1b14']} position={[0, -1.8, 0]} />
      <OrbitControls
        ref={controls}
        makeDefault
        enablePan={false}
        enableDamping
        dampingFactor={.065}
        minDistance={7.4}
        maxDistance={14.6}
        minPolarAngle={.55}
        maxPolarAngle={1.34}
        target={[0, .15, 0]}
      />
    </>
  )
}

const supportsWebGL = () => {
  try {
    const canvas = document.createElement('canvas')
    return Boolean(canvas.getContext('webgl2') || canvas.getContext('webgl'))
  } catch {
    return false
  }
}

export function ParticleTerrainScene(props: ParticleTerrainSceneProps) {
  const profile = useMotionProfile()
  const [webgl, setWebgl] = useState<boolean | null>(null)
  const pointCount = particleCountForProfile(profile)
  useEffect(() => setWebgl(supportsWebGL()), [])
  return (
    <div className={`particle-terrain-scene motion-${profile} ${props.scanning ? 'is-scanning' : ''}`} role="img" aria-label={`程序化粒子生态地形，${props.periodLabel}。高程色彩为概念编码，九城光点使用真实${props.metric === 'pm25' ? 'PM2.5' : 'PM10'}数据。`}>
      {webgl ? (
        <Canvas
          aria-hidden="true"
          dpr={profile === 'full' ? [1, 1.55] : 1}
          camera={{ position: [8.9, 6.5, 9.8], fov: 39, near: .1, far: 40 }}
          gl={{ antialias: profile === 'full', alpha: false, powerPreference: 'high-performance' }}
        >
          <Scene props={props} profile={profile} />
        </Canvas>
      ) : (
        <div className="particle-terrain-fallback" aria-hidden="true"><i /><i /><i /><span /></div>
      )}
      <div className="particle-screen-grid" aria-hidden="true" />
      <div className="particle-vignette" aria-hidden="true" />
      <p className="particle-model-note">{pointCount.toLocaleString()} SURFACE PARTICLES · PROCEDURAL CONCEPT TERRAIN / 非真实DEM</p>
    </div>
  )
}

